function simplePackageCostMessage(sku:MaterialSkuRecord):string {
 const cost=listMaterialCostVersions(sku.materialSkuId).at(-1),relation=cost?.pricingUnitRelationId?listMaterialUnitRelations(sku.materialSkuId,true).find(r=>r.relationId===cost.pricingUnitRelationId):null
 const next=`${value('packageType')||'包装'}（${value('packageContent')||'待填写'} ${value('packageContentUnit')||sku.mainUnit}）`
 if(!cost)return `本次包装：${next}。\n尚未维护标准报价。保存包装只维护含量与换算，不生成标准成本。`
 if(!relation?.packageSpecId)return `本次包装：${next}。\n当前标准报价按 ${cost.pricingUnit} 计价，未采用此包装。保存新包装不会变更当前报价。`
 const adopted=`${relation.auxUnitId}（${relation.mainQtyPerAux} ${sku.mainUnit}） · 换算 v${relation.version}`
 return `当前标准报价采用：${adopted}；采购 ${cost.purchaseStandardCny??'待维护'} RMB/${cost.pricingUnit}，基础运输 ${cost.transportStandardCny??'待维护'} RMB/${cost.pricingUnit}。\n本次包装：${next}。保存后当前报价继续沿用上述旧版本，新包装未用于报价。\n如需采用新的包装报价，请到标准成本选择新包装依据并维护对应金额；旧采购和正式技术资料仍使用原版本。`
}
function describeApprovalScope(ids:readonly string[],action:'SUBMIT'|'APPROVE'|'REJECT'):string {
 const scopes=new Map<string,{root:MaterialArchiveRecord;skus:MaterialSkuRecord[];whole:boolean}>()
 for(const id of ids){const selected=getMaterialSkuRecordById(id),root=getMaterialArchiveById(selected?.materialId||id);if(!root)continue
  const whole=!selected||simpleKind(root.kind)&&root.approvalStatus!=='APPROVED',key=whole?root.materialId:id
  if(scopes.has(key))continue
  const skus=whole?listMaterialSkuRecordsByMaterialId(root.materialId).filter(sku=>action==='SUBMIT'?sku.approvalStatus!=='APPROVED':sku.approvalStatus==='PENDING'):[selected!]
  scopes.set(key,{root,skus,whole})
 }
 const groups=[...scopes.values()],rootCount=groups.filter(g=>g.whole).length,skuCount=groups.reduce((n,g)=>n+g.skus.length,0)
 return `确认${action==='SUBMIT'?'提交审核':action==='APPROVE'?'审核通过':'驳回'}以下实际处理范围？\n本次涉及 ${rootCount} 个主档、${skuCount} 个规格。\n`+groups.map(g=>`${g.whole?'主档及所属待审规格':'单独规格'}：${g.root.materialCode}（${g.root.materialName}）\n${g.skus.map(sku=>`  ${sku.materialSkuCode} · ${sku.specName}`).join('\n')||'  无待处理规格'}`).join('\n\n')+'\n\n未审核通过的主档按整档处理，上面列出的兄弟规格一并处理。'
}
