function copySimpleAssets(result:MaterialSkuRecord,sourceId:string,includeRoot=false):void {
 const original=getMaterialSkuRecordById(sourceId);if(!original)return
 const assets=listMaterialAssets(original.materialId).filter(asset=>(asset.materialSkuId===sourceId||includeRoot&&!asset.materialSkuId)&&['IDENTIFICATION','SPECIFICATION'].includes(asset.role))
 for(const asset of assets)addMaterialAsset({materialId:result.materialId,materialSkuId:asset.materialSkuId?result.materialSkuId:undefined,role:asset.role,name:asset.name,url:asset.url,fileId:asset.fileId,fileName:asset.fileName,mimeType:asset.mimeType,sizeBytes:asset.sizeBytes,sortOrder:asset.sortOrder})
}
function copySimpleCost(result:MaterialSkuRecord,sourceId:string):void {
 const original=getMaterialSkuRecordById(sourceId);if(!original)throw new Error('复制成本的来源规格不存在。')
 const source=listMaterialCostVersions(sourceId).at(-1);if(!source)return
 const conversion=getMaterialCostUnitConversion(sourceId,result.mainUnit||result.pricingUnit,source.pricingUnit,source.pricingUnitRelationId)
 if(conversion.factor===null)throw new Error('来源成本缺少换算依据，请先补齐关系或取消复制标准成本。')
 saveMaterialStandardCost(result.materialSkuId,{purchaseStandardCny:source.purchaseStandardCny==null?null:materialDecimalMultiply(source.purchaseStandardCny,conversion.factor),transportStandardCny:source.transportStandardCny==null?null:materialDecimalMultiply(source.transportStandardCny,conversion.factor),purchaseIncludesTransport:source.purchaseIncludesTransport,pricingUnit:result.mainUnit,changeReason:'复制规格时明确选择复制标准成本'})
}
function renderSimpleLegacyHistory(sku:MaterialSkuRecord):string {
 const definition=getMaterialProcessDefinition(sku.materialSkuId),versions=listMaterialCostVersions(sku.materialSkuId)
 return `<details class="mt-5 border-t pt-4"><summary class="cursor-pointer text-sm">既有费用与资料记录（只读）</summary><div class="mt-4">${rows([['既有投入',getMaterialSkuRecordById(sku.inputSkuId||'')?.materialSkuCode],['既有工艺',definition?MATERIAL_PROCESS_NAMES[definition.processType]:'原资料未记录'],['资料版本',definition?.processVersionId]])}${simpleTable(['时间','说明','既有采购','既有运输','既有加工费用'],versions.slice().reverse().map(v=>[h(v.effectiveAt),h(v.changeReason),h(v.purchaseStandardCny??'未记录'),h(v.transportStandardCny??'未记录'),h(v.processStandardCny??'未记录')]))}</div></details>`
}
function describeSimpleUse(id:string,status:string):string {
 const sku=getMaterialSkuRecordById(id),root=getMaterialArchiveById(sku?.materialId||id)
 if(!root||!simpleKind(root.kind)||status!=='ACTIVE')return `确认${status==='ACTIVE'?'启用':status==='ARCHIVED'?'归档':'停用'}此档案？${status==='ARCHIVED'?'存在活动引用时不可归档。':''}`
 if(sku)return root.status==='ACTIVE'?`确认启用规格 ${sku.materialSkuCode}（${sku.specName}）？`:`确认同时启用主档 ${root.materialCode} 和规格 ${sku.materialSkuCode}（${sku.specName}）？本次只启用该规格。`
 const first=listMaterialSkuRecordsByMaterialId(root.materialId)[0]
 return `确认启用主档 ${root.materialCode}${first?`及首个规格 ${first.materialSkuCode}（${first.specName}）`:''}？本次只启用首个规格。`
}
function applySimpleApproval(id:string,action:'SUBMIT'|'APPROVE'|'REJECT',reason:string):void {
 const sku=getMaterialSkuRecordById(id),root=getMaterialArchiveById(sku?.materialId||id)
 if(root&&simpleKind(root.kind)&&sku&&root.approvalStatus!=='APPROVED')setMaterialApproval(root.materialId,action,reason)
 else setMaterialApproval(id,action,reason)
}
function applySimpleUse(id:string,status:'ACTIVE'|'INACTIVE'|'ARCHIVED',reason=''):void {
 const sku=getMaterialSkuRecordById(id),root=getMaterialArchiveById(sku?.materialId||id)
 if(root&&simpleKind(root.kind)&&status==='ACTIVE'){
  if(root.status!=='ACTIVE')setMaterialUseStatus(root.materialId,status)
  if(sku)setMaterialUseStatus(sku.materialSkuId,status)
  else {const first=listMaterialSkuRecordsByMaterialId(root.materialId)[0];if(first&&first.status!=='ACTIVE')setMaterialUseStatus(first.materialSkuId,status)}
 }else setMaterialUseStatus(id,status,reason)
}

